       font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       color: var(--text);
       background:
         radial-gradient(circle at top left, rgba(124, 58, 237, 0.18), transparent 32%),
         radial-gradient(circle at top right, rgba(37, 99, 235, 0.14), transparent 28%),
         linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
       display: grid;
       place-items: center;
       padding: 32px 16px;
     }

     .quiz-shell {
       width: min(100%, 880px);
       background: var(--panel);
       backdrop-filter: blur(16px);
       border: 1px solid var(--panel-border);
       border-radius: var(--radius);
       box-shadow: var(--shadow);
       overflow: hidden;
     }

     .hero {
       padding: 40px 40px 24px;
       background: linear-gradient(135deg, rgba(37, 99, 235, 0.12), rgba(124, 58, 237, 0.12));
       border-bottom: 1px solid rgba(148, 163, 184, 0.18);
     }

     .eyebrow {
       display: inline-flex;
       align-items: center;
       gap: 8px;
       padding: 8px 12px;
       border-radius: 999px;
       background: rgba(255, 255, 255, 0.75);
       color: var(--primary);
       font-size: 0.82rem;
       font-weight: 700;
       letter-spacing: 0.04em;
       text-transform: uppercase;
     }

     h1 {
       margin: 18px 0 12px;
       font-size: clamp(2rem, 4vw, 3rem);
       line-height: 1.05;
     }

     .hero p {
       margin: 0;
       max-width: 56ch;
       color: var(--muted);
       font-size: 1.02rem;
       line-height: 1.7;
     }

     form {
       padding: 32px 40px 40px;
     }

     .form-field + .form-field {
       margin-top: 24px;
     }

     .form-field {
       padding: 24px;
       border-radius: 22px;
       border: 1px solid rgba(148, 163, 184, 0.22);
       background: linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(248, 250, 252, 0.94));
     }

     .question-header {
       display: flex;
       flex-wrap: wrap;
       align-items: baseline;
       justify-content: space-between;
       gap: 12px;
       margin-bottom: 10px;
     }

     .question-number {
       font-size: 0.85rem;
       font-weight: 700;
       letter-spacing: 0.08em;
       text-transform: uppercase;
       color: var(--accent);
     }

     .question-title {
       margin: 0;
       font-size: 1.2rem;
       line-height: 1.4;
     }

     .help-text {
       margin: 0 0 18px;
       color: var(--muted);
       font-size: 0.96rem;
       line-height: 1.6;
     }

     .choices {
       display: grid;
       gap: 12px;
     }

     .choice {
       position: relative;
     }

     .choice input {
       position: absolute;
       opacity: 0;
       inset: 0;
       cursor: pointer;
     }

     .choice label {
       display: flex;
       align-items: center;
       gap: 14px;
       width: 100%;
       padding: 16px 18px;
       border-radius: 18px;
       border: 1px solid rgba(148, 163, 184, 0.26);
       background: #ffffff;
       transition: transform 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
       cursor: pointer;
     }

     .choice label::before {
       content: "";
       width: 22px;
       height: 22px;
       flex: 0 0 22px;
       border-radius: 7px;
       border: 1.5px solid #94a3b8;
       background: #fff;
       box-shadow: inset 0 0 0 0 var(--primary);
       transition: all 0.2s ease;
     }

     .choice input:focus-visible + label {
       outline: 3px solid rgba(37, 99, 235, 0.25);
       outline-offset: 2px;
     }

     .choice input:checked + label {
       border-color: rgba(37, 99, 235, 0.4);
       background: var(--primary-soft);
       box-shadow: 0 12px 30px rgba(37, 99, 235, 0.12);
       transform: translateY(-1px);
     }

     .choice input:checked + label::before {
       border-color: var(--primary);
       background: var(--primary);
       box-shadow: inset 0 0 0 5px #ffffff;
     }

     .form-actions {
       display: flex;
       flex-wrap: wrap;
       align-items: center;
       gap: 16px;
       margin-top: 32px;
     }

     button {
       appearance: none;
       border: 0;
       border-radius: 999px;
       padding: 15px 24px;
       font: inherit;
       font-weight: 700;
       color: #ffffff;
       background: linear-gradient(135deg, var(--primary), #4f46e5);
       box-shadow: 0 16px 30px rgba(37, 99, 235, 0.28);
       cursor: pointer;
       transition: transform 0.2s ease, box-shadow 0.2s ease;
     }

     button:hover {
       transform: translateY(-1px);
       box-shadow: 0 18px 32px rgba(37, 99, 235, 0.32);
     }

     button:focus-visible {
       outline: 3px solid rgba(37, 99, 235, 0.25);
       outline-offset: 3px;
     }

     .result {
       min-height: 24px;
       font-weight: 600;
       color: var(--success);
     }

     @media (max-width: 720px) {
       .hero,
       form {
         padding-left: 20px;
         padding-right: 20px;
       }

       .form-field {
         padding: 20px;
       }
     }
   </style>
 </head>
 <body>
   <main class="quiz-shell">
     <section class="hero">
       <div class="eyebrow">Interactive quiz</div>
       <h1>Computer Languages Quiz</h1>
       <p>Select all answers that apply for each question. Every question supports multiple correct answers.</p>
     </section>

     <form id="quiz-form">
       <div class="form-field">
