         </div>
         <p class="help-text">Choose every answer you believe fits. There can be more than one correct option.</p>
         <div class="choices">
           <div class="choice">
             <input type="checkbox" id="q1-css" name="q1" value="CSS">
             <label for="q1-css">CSS</label>
           </div>
           <div class="choice">
')
